CREATE OR REPLACE FUNCTION public.tasks_page(_status text DEFAULT 'open',_search text DEFAULT '',_offset integer DEFAULT 0,_limit integer DEFAULT 25,_today boolean DEFAULT false,_team boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb;BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'سجل الدخول';END IF;IF _team AND NOT public.has_permission('tasks.manage','view') THEN RAISE EXCEPTION 'مهام الفريق غير مسموحة';END IF;WITH f AS(SELECT t.* FROM public.tasks t WHERE public.task_can_read(t) AND (_team OR t.assignee_user_id=auth.uid()) AND (_status='all' OR t.status=_status) AND (_search='' OR t.title ILIKE '%'||_search||'%') AND (NOT _today OR (t.assignee_user_id=auth.uid() AND t.due_at<((now() AT TIME ZONE 'Asia/Riyadh')::date+1)::timestamp AT TIME ZONE 'Asia/Riyadh'))),p AS(SELECT * FROM f ORDER BY due_at,id LIMIT least(greatest(_limit,1),100) OFFSET greatest(_offset,0)) SELECT jsonb_build_object('rows',coalesce((SELECT jsonb_agg(to_jsonb(p)) FROM p),'[]'),'count',(SELECT count(*) FROM f),'as_of',now()) INTO result;RETURN result;END $$;
COMMENT ON FUNCTION public.tasks_page(text,text,integer,integer,boolean) IS 'DEPRECATED: use six-argument tasks_page with explicit own/team scope';
CREATE OR REPLACE FUNCTION public.task_assignees() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('user_id',p.user_id,'name',coalesce(p.display_name,'موظف'),'role',a.role)),'[]') FROM public.profiles p JOIN public.user_role_assignments a ON a.user_id=p.user_id WHERE a.is_active AND a.role NOT IN('user','tenant','investor','investor_viewer','manager') AND public.task_staff_active(p.user_id) AND public.has_permission('tasks.manage','edit') $$;
REVOKE ALL ON FUNCTION public.tasks_page(text,text,integer,integer,boolean,boolean),public.task_assignees() FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.tasks_page(text,text,integer,integer,boolean,boolean),public.task_assignees() TO authenticated;
SELECT to_regprocedure('public.tasks_page(text,text,integer,integer,boolean,boolean)') IS NOT NULL AS own_team_scope_ready;